<?php $title='All cases';require 'header.php';$q=trim($_GET['q']??'');$status=$_GET['status']??'';$priority=$_GET['priority']??'';$sql="SELECT * FROM disputes WHERE 1";$types='';$vals=[];if($q){$sql.=" AND (case_no LIKE CONCAT('%',?,'%') OR claimant_name LIKE CONCAT('%',?,'%') OR claimant_email LIKE CONCAT('%',?,'%') OR transaction_ref LIKE CONCAT('%',?,'%'))";$types.='ssss';array_push($vals,$q,$q,$q,$q);}if($status){$sql.=" AND status=?";$types.='s';$vals[]=$status;}if($priority){$sql.=" AND priority=?";$types.='s';$vals[]=$priority;}$sql.=" ORDER BY created_at DESC";$st=db()->prepare($sql);if($types)$st->bind_param($types,...$vals);$st->execute();$list=rows($st);?>
<div class="admin-head"><div><div class="kicker"><span></span> CASE QUEUE</div><h1>All disputes</h1></div></div><form class="filters"><input name="q" value="<?=h($q)?>" placeholder="Search case, name, email, transaction"><select name="status"><option value="">All statuses</option><?php foreach(['submitted','under_review','awaiting_response','resolved','closed','rejected'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=h(label($s))?></option><?php endforeach;?></select><select name="priority"><option value="">All priorities</option><?php foreach(['low','normal','high','urgent'] as $p):?><option value="<?=$p?>" <?=$priority===$p?'selected':''?>><?=h(ucfirst($p))?></option><?php endforeach;?></select><button class="btn dark">Filter</button></form>
<section class="admin-panel"><table><thead><tr><th>Case</th><th>Claimant</th><th>Dispute</th><th>Priority</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($list as $r):?><tr><td><a class="mono" href="case.php?id=<?=$r['id']?>"><?=h($r['case_no'])?></a></td><td><b><?=h($r['claimant_name'])?></b><small><?=h($r['claimant_email'])?></small></td><td><?=h($r['dispute_type'])?></td><td><span class="priority <?=h($r['priority'])?>"><?=h(ucfirst($r['priority']))?></span></td><td><span class="status <?=h($r['status'])?>"><?=h(label($r['status']))?></span></td><td><?=h(date('M j, Y',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></section><?php require 'footer.php';?>